params.command:
$ErrorActionPreference='Stop'
$dest = Join-Path $env:TEMP 'shipit-20260929-0928-agentcontrol-release-0a87bb6a'
if (Test-Path $dest) { Remove-Item -Recurse -Force $dest }
git clone --no-checkout https://github.com/fengie/mhw-mods.git $dest
git -C $dest fetch origin 0a87bb6a021fabd76f1de452dcb721ee35d58e40
git -C $dest checkout --detach 0a87bb6a021fabd76f1de452dcb721ee35d58e40
$actual = (git -C $dest rev-parse HEAD).Trim()
if ($actual -ne '0a87bb6a021fabd76f1de452dcb721ee35d58e40') { throw "HEAD mismatch: $actual" }
Push-Location (Join-Path $dest 'tools\agent-control')
try {
  node --version
  npm run check
  node --test --test-reporter tap test/*.test.mjs
} finally { Pop-Location }
$dirty = (git -C $dest status --porcelain)
if ($dirty) { throw "verification checkout dirty: $dirty" }
Write-Output "VERIFIED_HEAD=$actual"
Write-Output "WORKTREE_CLEAN=true"
